#include <bits/stdc++.h>
using namespace std;

const int INF = 0x3f3f3f3f;
const int MAXN = 410;
const int MAXM = 200020;
const int LIM = 12;
const int dx[4] = {-1, 0, 1, 0};
const int dy[4] = {0, 1, 0, -1};

char g[MAXN][MAXN], h[MAXN][MAXN];
int tim[LIM][LIM], dis[LIM][LIM];
int n, t;

bool inside(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

void bfs1(int sx, int sy) {
    memset(tim, 0x3f, sizeof(tim));
    queue<int> q;
    q.push(sx * 10 + sy);
    tim[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front() / 10, y = q.front() % 10;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (inside(nx, ny) && g[nx][ny] >= '0' && g[nx][ny] <= '9' && tim[nx][ny] > tim[x][y] + 1) {
                tim[nx][ny] = tim[x][y] + 1;
                q.push(nx * 10 + ny);
            }
        }
    }
}

void bfs2(int sx, int sy) {
    memset(dis, 0x3f, sizeof(dis));
    queue<int> q;
    q.push(sx * 10 + sy);
    dis[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front() / 10, y = q.front() % 10;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (inside(nx, ny) && h[nx][ny] >= '0' && h[nx][ny] <= '9' && dis[nx][ny] > dis[x][y] + 1) {
                if (tim[nx][ny] >= dis[x][y] + 1) {
                    dis[nx][ny] = dis[x][y] + 1;
                    if (tim[nx][ny] > dis[nx][ny])
                        q.push(nx * 10 + ny);
                }
            }
        }
    }
}

struct MaxFlow {
    vector<int> head, to, nxt, cap, flow, level, it;
    int s, t, n;
    void init(int n_) {
        n = n_;
        head.assign(n, -1);
        to.clear();
        nxt.clear();
        cap.clear();
        flow.clear();
        level.resize(n);
        it.resize(n);
    }
    void addEdge(int u, int v, int c) {
        int id = (int)to.size();
        to.push_back(v);
        cap.push_back(c);
        flow.push_back(0);
        nxt.push_back(head[u]);
        head[u] = id;
        to.push_back(u);
        cap.push_back(0);
        flow.push_back(0);
        nxt.push_back(head[v]);
        head[v] = id ^ 1;
    }
    bool bfs() {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];
                if (level[v] == -1 && cap[e] > flow[e]) {
                    level[v] = level[u] + 1;
                    q.push(v);
                }
            }
        }
        return level[t] != -1;
    }
    int dfs(int u, int a) {
        if (u == t || a == 0) return a;
        int ret = 0;
        for (int &e = it[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (level[v] == level[u] + 1 && cap[e] > flow[e]) {
                int f = dfs(v, min(a, cap[e] - flow[e]));
                if (f > 0) {
                    flow[e] += f;
                    flow[e ^ 1] -= f;
                    a -= f;
                    ret += f;
                    if (a == 0) break;
                }
            }
        }
        return ret;
    }
    int maxflow(int S, int T) {
        s = S;
        t = T;
        int ans = 0;
        while (bfs()) {
            it = head;
            ans += dfs(s, INF);
        }
        return ans;
    }
} mf;

int main() {
    scanf("%d%d", &n, &t);
    for (int i = 0; i < n; ++i) scanf("%s", g[i]);
    for (int i = 0; i < n; ++i) scanf("%s", h[i]);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (g[i][j] == 'Z')
                bfs1(i, j);

    int S = 0, T = n * n * 2 + 1;
    mf.init(T + 1);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (g[i][j] > '0' && g[i][j] <= '9')
                mf.addEdge(S, i * n + j + 1, g[i][j] - '0');
            if (h[i][j] > '0' && h[i][j] <= '9')
                mf.addEdge(n * n + i * n + j + 1, T, h[i][j] - '0');
        }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (g[i][j] > '0' && g[i][j] <= '9') {
                bfs2(i, j);
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y)
                        if (h[x][y] > '0' && h[x][y] <= '9' && dis[x][y] <= t)
                            mf.addEdge(i * n + j + 1, n * n + x * n + y + 1, INF);
            }

    printf("%d\n", mf.maxflow(S, T));
    return 0;
}
